src='''from collections import deque, Counter
def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); out=[row[:] for row in grid]
    for r in range(h):
      for c in range(w):
        if grid[r][c]==0 or (r,c) in seen: continue
        q=deque([(r,c)]); seen.add((r,c)); cells=[]
        while q:
          y,x=q.popleft(); cells.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=y+dy,x+dx
            if 0<=a<h and 0<=b<w and grid[a][b]!=0 and (a,b) not in seen:
              seen.add((a,b)); q.append((a,b))
        cnt=Counter(grid[y][x] for y,x in cells); colors=sorted(cnt,key=lambda k:-cnt[k]); mapping={colors[i]:colors[-1-i] for i in range(len(colors))}
        for y,x in cells: out[y][x]=mapping[grid[y][x]]
    return out
'''
